              <path d="M10 20 Q35 18, 60 20" fill="none" stroke="#fda4af" strokeWidth="1.5" opacity="0.6" strokeLinecap="round" />
              {/* Tip highlight */}
              <ellipse cx="62" cy="20" rx="4" ry="3" fill="#fecdd3" opacity="0.7" />
